'use strict';
const $=s=>document.querySelector(s);let rows=[],budgetOnly=false,history=[],meta={},targets=[];
const num=n=>Number(n||0).toLocaleString('ko-KR');const eok=n=>n==null?'—':(n/10000).toLocaleString('ko-KR',{maximumFractionDigits:2})+'억';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const py=m=>m?Math.round(Number(m)/3.3058*10)/10:null;
async function loadData(){const r=await fetch('buy_watchlist_master.json?v='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error('관심단지 데이터 로드 실패');const d=await r.json();if(!Array.isArray(d.items)||d.items.length<30)throw Error('관심단지 데이터가 불완전합니다');meta={collected_at:d.kb_collected_at};return d.items.flatMap(x=>(x.types||[]).map(t=>({...t,complex_id:x.complex_id,name:x.user_name||x.kb_name,district:x.district,dong:x.dong,households:x.households,built_ymd:x.built_ymd,supply_pyeong:py(t.supply_m2)})))}
async function loadWatch(){try{const d=await (await fetch('buy_watchlist_master.json',{cache:'no-store'})).json();return new Set((d.items||[]).map(x=>Number(x.complex_id)).filter(Boolean))}catch(_){return new Set()}}
async function loadTargets(){const r=await fetch('buy_watchlist_targets.json?v='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error('목표 평형 데이터 로드 실패');const d=await r.json();if(!Array.isArray(d.items)||d.items.length!==39)throw Error('목표 단지 데이터가 불완전합니다');return d.items}
function targetFor(r){const norm=s=>String(s||'').replace(/\s+/g,'').replace(/아파트$/,'').replace(/\(.*?\)/g,'');const rn=norm(r.name||r.user_name);return targets.find(t=>{const tn=norm(t.name);return tn===rn||tn.includes(rn)||rn.includes(tn)})}
function isTarget(r){const t=targetFor(r);if(!t)return false;if(t.min_pyeong==null)return true;const vals=[r.supply_pyeong,r.type_label,py(r.supply_m2)].map(v=>parseFloat(String(v??'').match(/\d+(?:\.\d+)?/)?.[0]||'NaN')).filter(Number.isFinite);return vals.some(n=>n>=Number(t.min_pyeong)-0.8&&n<=Number(t.max_pyeong)+0.8)}
function targetLabel(r){return targetFor(r)?.selection||''}
async function loadHistory(){const c=globalThis.KB_PRICE_CONFIG;if(!c?.supabaseAnonKey||c.supabaseAnonKey.startsWith('REPLACE_'))return[];try{const h={apikey:c.supabaseAnonKey,Authorization:'Bearer '+c.supabaseAnonKey};const r=await fetch(c.supabaseUrl+'/rest/v1/kb_price_history?select=complex_id,area_id,general_price_manwon,collected_at&order=collected_at.asc',{headers:h,cache:'no-store'});return r.ok?await r.json():[]}catch(_){return[]}}
function budget(){return Number($('#budget').value||15)*10000}
function score(r){let s=0,b=budget(),p=Number(r.general_price_manwon);if(p&&p<=b)s+=40;else if(p&&p<=b+20000)s+=22;else if(p&&p<=b+40000)s+=10;if((r.households||0)>=1000)s+=25;else if((r.households||0)>=500)s+=18;else if((r.households||0)>=300)s+=12;const y=Number(String(r.built_ymd||'0').slice(0,4));if(y>=2015)s+=20;else if(y>=2005)s+=14;else if(y>=1995)s+=8;if((r.type_households||0)>=200)s+=15;else if((r.type_households||0)>=100)s+=10;else s+=5;return Math.min(100,s)}
function reason(r){const a=[];if(Number(r.general_price_manwon)<=budget())a.push('예산 이내');else if(Number(r.general_price_manwon)<=budget()+20000)a.push('예산 근접');if((r.households||0)>=1000)a.push('1천세대+');else if((r.households||0)>=500)a.push('500세대+');const y=Number(String(r.built_ymd||'').slice(0,4));if(y>=2015)a.push('준신축·신축');if((r.type_households||0)>=200)a.push('해당 타입 세대수 많음');return a.length?a.join(' · '):'가격·입지 추가 확인'}
function delta(r){const hs=history.filter(x=>Number(x.complex_id)===Number(r.complex_id)&&Number(x.area_id)===Number(r.area_id)&&x.general_price_manwon!=null);if(hs.length<2)return null;return Number(hs.at(-1).general_price_manwon)-Number(hs.at(-2).general_price_manwon)}
function since(r){const hs=history.filter(x=>Number(x.complex_id)===Number(r.complex_id)&&Number(x.area_id)===Number(r.area_id)&&x.general_price_manwon!=null);if(hs.length<2)return null;return Number(hs.at(-1).general_price_manwon)-Number(hs[0].general_price_manwon)}
function dtext(v){return v==null?'<span class="muted">기록 대기</span>':v===0?'<span class="flat">보합</span>':v>0?'<span class="up">▲ '+eok(v)+'</span>':'<span class="down">▼ '+eok(Math.abs(v))+'</span>'}
function renderTop(){const b=budget(),priced=rows.filter(r=>r.general_price_manwon!=null),ids=new Set(rows.map(r=>r.complex_id));$('#complexCount').textContent=ids.size;$('#underCount').textContent=priced.filter(r=>r.general_price_manwon<=b).length;$('#nearCount').textContent=priced.filter(r=>r.general_price_manwon>b&&r.general_price_manwon<=b+20000).length;const mn=[...priced].sort((a,b)=>a.general_price_manwon-b.general_price_manwon)[0];$('#minPrice').textContent=mn?eok(mn.general_price_manwon):'—';$('#minPriceName').textContent=mn?mn.name+' '+mn.type_label+'평':'';$('#headline').textContent=priced.filter(r=>r.general_price_manwon<=b).length+'개 평형이 현재 가용자산 범위 안에 있어요';$('#subline').textContent='가용자산 '+eok(b)+' · KB 일반가 기준';
const ds=rows.map(delta).filter(v=>v!=null);const up=ds.filter(v=>v>0).length,dn=ds.filter(v=>v<0).length,fl=ds.filter(v=>v===0).length;$('#weekly').innerHTML=ds.length?'<div><b class="up">'+up+'</b><span>상승</span></div><div><b class="down">'+dn+'</b><span>하락</span></div><div><b>'+fl+'</b><span>보합</span></div>':'<div class="nodata">주간 이력이 쌓이면 상승·하락을 자동 비교합니다.</div>';
const bands=[['예산 이내',priced.filter(r=>r.general_price_manwon<=b).length],['+'+2+'억 이내',priced.filter(r=>r.general_price_manwon>b&&r.general_price_manwon<=b+20000).length],['+'+2+'억 초과',priced.filter(r=>r.general_price_manwon>b+20000).length]];$('#budgetBands').innerHTML=bands.map((x,i)=>'<div><span>'+x[0]+'</span><b>'+x[1]+'개 평형</b><i style="width:'+Math.min(100,x[1]/Math.max(1,priced.length)*100)+'%"></i></div>').join('');
}
function renderShort(){const seen=new Set(),best=[...rows].filter(r=>r.general_price_manwon!=null).sort((a,b)=>score(b)-score(a)||a.general_price_manwon-b.general_price_manwon).filter(r=>{const k=r.complex_id;if(seen.has(k))return false;seen.add(k);return true}).slice(0,5);$('#shortlist').innerHTML=best.map((r,i)=>'<article><span class="rank">'+(i+1)+'</span><div><b>'+esc(r.name)+'</b><small>'+esc(r.district)+' · '+r.type_label+'평 · '+num(r.households)+'세대</small></div><strong>'+eok(r.general_price_manwon)+'</strong><div class="meter"><i style="width:'+score(r)+'%"></i></div><small>검토도 '+score(r)+'/100 · '+reason(r)+'</small></article>').join('')}
function renderTable(){let a=[...rows],q=$('#search').value.trim();if(q)a=a.filter(r=>(r.name+' '+r.district+' '+(r.dong||'')).includes(q));if(budgetOnly)a=a.filter(r=>r.general_price_manwon!=null&&r.general_price_manwon<=budget());const s=$('#sort').value,b=budget();a.sort((x,y)=>s==='priceDesc'?(y.general_price_manwon||0)-(x.general_price_manwon||0):s==='budget'?Math.abs((x.general_price_manwon||1e9)-b)-Math.abs((y.general_price_manwon||1e9)-b):s==='households'?(y.households||0)-(x.households||0):s==='newest'?String(y.built_ymd||'').localeCompare(String(x.built_ymd||'')):(x.general_price_manwon??1e12)-(y.general_price_manwon??1e12));$('#body').innerHTML=a.map(r=>{const p=r.general_price_manwon,d=p==null?null:p-b;return '<tr><td><b>'+esc(r.name)+'</b><small>'+esc(r.district)+' '+esc(r.dong||'')+' · '+r.type_label+'평형 ('+(r.supply_pyeong||py(r.supply_m2)||'—')+'평)</small></td><td><strong>'+eok(p)+'</strong></td><td>'+(d==null?'—':d<=0?'<span class="ok">'+eok(Math.abs(d))+' 여유</span>':'<span class="over">+'+eok(d)+'</span>')+'</td><td>'+dtext(delta(r))+'</td><td>'+dtext(since(r))+'</td><td><b>'+num(r.households)+'세대</b><small>'+String(r.built_ymd||'—').slice(0,4)+'년 · 타입 '+num(r.type_households)+'세대</small></td><td><span class="score">'+score(r)+'</span><small>'+reason(r)+'</small></td><td><button class="live" data-name="'+esc(r.name)+'" data-area="'+(r.supply_m2||0)+'">최저호가 조회</button></td></tr>'}).join('')}
function renderHistoryOptions(){const seen=new Set();$('#historySelect').innerHTML=rows.filter(r=>{const k=r.complex_id+'/'+r.area_id;if(seen.has(k))return false;seen.add(k);return true}).map(r=>'<option value="'+r.complex_id+'/'+r.area_id+'">'+esc(r.name)+' · 목표 '+esc(targetLabel(r))+' · '+r.type_label+'평</option>').join('');renderHistory()}
function renderHistory(){const [c,a]=($('#historySelect').value||'').split('/').map(Number),r=rows.find(x=>Number(x.complex_id)===c&&Number(x.area_id)===a),hs=history.filter(x=>Number(x.complex_id)===c&&Number(x.area_id)===a&&x.general_price_manwon!=null);if(!r){$('#historyBox').innerHTML='';return}if(hs.length<2){$('#historyBox').innerHTML='<div class="history-empty"><b>'+esc(r.name)+' '+r.type_label+'평</b><span>현재 '+eok(r.general_price_manwon)+'</span><p>금요일 수집 이력이 누적되면 여기에서 과거→현재 가격 그래프와 변동폭을 보여줍니다.</p></div>';return}const vals=hs.map(x=>Number(x.general_price_manwon)),lo=Math.min(...vals),hi=Math.max(...vals),w=760,h=180,pad=24,pts=vals.map((v,i)=>[(pad+i*(w-pad*2)/Math.max(1,vals.length-1)),h-pad-(v-lo)/Math.max(1,hi-lo)*(h-pad*2)]);$('#historyBox').innerHTML='<div class="chart-meta"><b>'+eok(vals[0])+' → '+eok(vals.at(-1))+'</b><span>'+hs.length+'회 기록</span></div><svg viewBox="0 0 '+w+' '+h+'" role="img"><polyline points="'+pts.map(p=>p.join(',')).join(' ')+'" fill="none" stroke="currentColor" stroke-width="4"/>'+pts.map(p=>'<circle cx="'+p[0]+'" cy="'+p[1]+'" r="5"/>').join('')+'</svg>'}
async function live(btn){btn.disabled=true;btn.textContent='조회중…';try{const u='http://127.0.0.1:17330/live-listing?name='+encodeURIComponent(btn.dataset.name)+'&area='+Math.round(Number(btn.dataset.area));const r=await fetch(u,{cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'조회 실패');btn.textContent=d.lowest?'최저 '+eok(d.lowest.priceManwon)+' · '+num(d.listingCount)+'건':'매물 없음'}catch(e){btn.textContent='조회 실패';btn.title=String(e.message||e)}finally{btn.disabled=false}}
function render(){renderTop();renderShort();renderTable()}
Promise.all([loadData(),loadWatch(),loadHistory(),loadTargets()]).then(([all,watch,h,t])=>{history=h;targets=t;const watched=all;rows=watched.filter(isTarget);const visibleComplexes=new Set(rows.map(r=>r.complex_id).filter(Boolean)).size;if(visibleComplexes<38)throw Error('관심단지 필터 결과가 불완전합니다 ('+visibleComplexes+'/38)');$('#updated').textContent='KB '+(meta.collected_at?new Date(meta.collected_at).toLocaleDateString('ko-KR'):'현재 자료')+' 기준';render();renderHistoryOptions()}).catch(e=>{$('#headline').textContent='자료를 불러오지 못했습니다';$('#subline').textContent=String(e.message||e)});
$('#budget').addEventListener('input',render);$('#search').addEventListener('input',renderTable);$('#sort').addEventListener('change',renderTable);$('#onlyBudget').onclick=e=>{budgetOnly=!budgetOnly;e.currentTarget.classList.toggle('active',budgetOnly);renderTable()};$('#historySelect').addEventListener('change',renderHistory);$('#body').addEventListener('click',e=>{const b=e.target.closest('.live');if(b)live(b)});
